-- NOVA Core internal gateway replay protection — 0003
-- Apply after 0002_tenant_isolation.sql and before exposing the private tenant API.
-- Request IDs are generated by the trusted gateway and consumed exactly once.
-- Expired rows may be pruned after their expiry; the API rejects stale timestamps
-- independently, so pruning must never be used as the freshness control.

CREATE TABLE internal_request_nonces (
  request_id TEXT PRIMARY KEY
    CHECK (length(trim(request_id)) BETWEEN 1 AND 80),
  issued_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL CHECK (expires_at > issued_at),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_internal_request_nonces_expiry
  ON internal_request_nonces(expires_at);
